import * as React from "react";
import * as SwitchPrimitive from "@radix-ui/react-switch";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: Switch — 16 variants
 *   Size        Default (32x18) | Small (24x14)
 *   State       Default | Focus | Disabled | Destructive
 *   Data state  Unchecked | Checked
 *
 * The `Size` axis is an addition over upstream shadcn. Track padding is 1px,
 * so the thumb is (height - 2). Unchecked track uses `input`, checked `primary`.
 */
const switchVariants = cva(
  cn(
    "peer inline-flex shrink-0 items-center rounded-full border border-transparent p-px",
    "transition-all outline-none",
    "data-[state=checked]:bg-primary data-[state=unchecked]:bg-input",
    "focus-visible:border-ring focus-visible:ring-ring-subtle focus-visible:ring-[3px]",
    "aria-invalid:border-destructive aria-invalid:ring-ring-destructive aria-invalid:ring-[3px]",
    "disabled:cursor-not-allowed disabled:opacity-50"
  ),
  {
    variants: {
      size: {
        default: "h-[18px] w-8",
        small: "h-3.5 w-6",
      },
    },
    defaultVariants: { size: "default" },
  }
);

const switchThumbVariants = cva(
  cn(
    "pointer-events-none block rounded-full bg-background ring-0 shadow-xs transition-transform",
    "data-[state=unchecked]:translate-x-0"
  ),
  {
    variants: {
      size: {
        default: "size-4 data-[state=checked]:translate-x-[14px]",
        small: "size-3 data-[state=checked]:translate-x-[10px]",
      },
    },
    defaultVariants: { size: "default" },
  }
);

function Switch({
  className,
  size,
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Root> & VariantProps<typeof switchVariants>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(switchVariants({ size }), className)}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(switchThumbVariants({ size }))}
      />
    </SwitchPrimitive.Root>
  );
}

export { Switch, switchVariants };
